-- À exécuter dans Supabase (SQL Editor) après chaque modification d'un chapitre premium.

insert into public.contenu_premium (cle, lecons) values ('base-de-donnees/requetes-select', $contenu$[{"slug":"projection-et-tri","titre":"SELECT : choisir les colonnes et trier","duree":"25 min","objectifs":["Écrire une requête SELECT … FROM …","Choisir les colonnes à afficher (projection)","Renommer une colonne avec AS et faire des calculs","Supprimer les doublons avec DISTINCT et trier avec ORDER BY"],"resume":{"duree":"1 min 30","scenes":[{"type":"titre","titre":"SELECT et ORDER BY","sousTitre":"Le résumé en 2 minutes","narration":"Choisir les colonnes et trier les résultats en SQL, en deux minutes."},{"type":"code","titre":"Lire une requête","lignes":["SELECT nom, prenom","FROM etudiant","ORDER BY nom;"],"etapes":[{"ligne":1,"variables":{"table":"etudiant"},"note":"FROM : dans quelle table ?"},{"ligne":0,"variables":{"table":"etudiant","colonnes":"nom, prenom"},"note":"SELECT : quelles colonnes ?"},{"ligne":2,"variables":{"table":"etudiant","colonnes":"nom, prenom","tri":"nom A → Z"},"sortie":"Bamba Ibrahim, Diallo Fatou…","note":"ORDER BY : dans quel ordre ?"}],"narration":"Une requête se lit dans cet ordre : FROM indique la table, SELECT les colonnes à afficher, et ORDER BY l'ordre des lignes."},{"type":"points","titre":"Les outils du SELECT","points":["* : toutes les colonnes","AS : renommer une colonne","DISTINCT : supprimer les doublons","ORDER BY … DESC : ordre décroissant"],"narration":"L'étoile affiche toutes les colonnes. AS renomme une colonne du résultat. DISTINCT supprime les lignes en double. Et ORDER BY suivi de DESC trie en ordre décroissant."},{"type":"comparaison","titre":"ASC ou DESC ?","colonnes":[{"nom":"ASC (par défaut)","texte":"Croissant : A → Z, 0 → 20, ancien → récent"},{"nom":"DESC","texte":"Décroissant : Z → A, 20 → 0, récent → ancien"}],"narration":"ASC, l'ordre croissant, est l'ordre par défaut. DESC donne l'ordre décroissant, par exemple pour classer les notes de la meilleure à la moins bonne."},{"type":"exemple","titre":"Les matières par importance","situation":"Un étudiant veut savoir sur quelles matières concentrer ses révisions : celles qui ont le plus gros coefficient.","langage":"SQL","code":["SELECT libelle, coefficient","FROM matiere","ORDER BY coefficient DESC,","         libelle;"],"resultat":["Algorithmique    | 3","Base de données  | 3","Comptabilité     | 2","Anglais          | 1"],"narration":"Exemple concret : trier les matières par coefficient décroissant. Pour les matières à égalité, on trie ensuite par libellé, dans l'ordre alphabétique."},{"type":"exemple","titre":"D'où viennent les étudiants ?","situation":"La direction veut la liste des villes d'origine, chacune une seule fois.","langage":"SQL","code":["SELECT DISTINCT ville","FROM etudiant","ORDER BY ville;"],"resultat":["Abidjan","Bouaké","Korhogo","San-Pédro","Yamoussoukro"],"narration":"Deuxième exemple : DISTINCT supprime les doublons. Abidjan apparaît quatre fois dans la table, mais une seule fois dans le résultat."},{"type":"defi","question":"Combien de colonnes affiche cette requête ?","code":["SELECT nom prenom","FROM etudiant;"],"reponse":"Une seule !","explication":"Sans virgule, « prenom » devient un alias : on affiche la colonne nom, renommée prenom.","narration":"À toi de jouer. Combien de colonnes affiche cette requête ? Regarde bien.","narrationReponse":"Réponse : une seule. Il manque la virgule : prénom devient un alias, et on affiche seulement la colonne nom, renommée."}]},"blocs":[{"type":"titre","contenu":"1. La structure d'une requête SELECT"},{"type":"texte","contenu":"La requête **SELECT** sert à **interroger** la base : elle ne modifie rien, elle affiche un résultat sous forme de tableau. C'est de loin la requête la plus utilisée, et la plus présente dans les sujets du BTS. Sa forme complète comporte six clauses, toujours dans cet ordre :"},{"type":"code","langage":"sql","code":"SELECT   colonnes à afficher        -- obligatoire\nFROM     table(s)                   -- obligatoire\nWHERE    condition sur les lignes   -- leçon 2\nGROUP BY regroupement               -- chapitre suivant\nHAVING   condition sur les groupes  -- chapitre suivant\nORDER BY tri;                       -- cette leçon"},{"type":"encadre","variante":"astuce","titre":"Écrire proprement","elements":["Les mots-clés SQL s'écrivent en **MAJUSCULES** par convention (le SGBD accepte aussi les minuscules).","On met **une clause par ligne** pour que la requête soit lisible.","La requête se termine par un **point-virgule**.","Les **textes** s'écrivent entre apostrophes simples : `'Abidjan'`. Les nombres, sans apostrophes : `12`."]},{"type":"titre","contenu":"2. Choisir les colonnes (la projection)"},{"type":"texte","contenu":"Après SELECT, on liste les colonnes voulues, séparées par des **virgules**, dans l'ordre où on veut les voir. `SELECT *` affiche toutes les colonnes : pratique pour découvrir une table, mais à éviter dans une copie d'examen quand la question précise les colonnes demandées."},{"type":"sql","base":"scolarite","titre":"Le nom, le prénom et la ville des étudiants","requete":"SELECT nom, prenom, ville\nFROM etudiant;","legende":"Change l'ordre des colonnes (par exemple `ville, nom`) et observe le résultat."},{"type":"encadre","variante":"attention","titre":"L'erreur classique : la virgule","contenu":"Une virgule en trop avant FROM (`SELECT nom, prenom, FROM etudiant`) provoque une erreur de syntaxe. Une virgule oubliée (`SELECT nom prenom`) est plus traîtresse : le SGBD comprend « la colonne nom, renommée prenom » et n'affiche qu'une seule colonne !"},{"type":"titre","contenu":"3. Renommer avec AS et calculer"},{"type":"texte","contenu":"Le mot-clé **AS** donne un nom plus parlant à une colonne du **résultat** (un « alias »). La table, elle, n'est pas modifiée. On peut aussi afficher des **calculs** (`+ - * /`) et assembler des textes avec l'opérateur `||` (en MySQL, on utilise plutôt la fonction `CONCAT`)."},{"type":"sql","base":"scolarite","titre":"Alias et calculs","requete":"SELECT matricule,\n       code_matiere AS matiere,\n       note AS note_sur_20,\n       note * 5 AS note_sur_100\nFROM note;","legende":"La colonne note_sur_100 n'existe pas dans la table : elle est calculée pour chaque ligne."},{"type":"sql","base":"scolarite","titre":"Assembler des textes","requete":"SELECT prenom || ' ' || nom AS etudiant,\n       'né(e) le ' || date_naissance AS naissance\nFROM etudiant;","legende":"En MySQL : `CONCAT(prenom, ' ', nom)`."},{"type":"titre","contenu":"4. Supprimer les doublons avec DISTINCT"},{"type":"texte","contenu":"Quand on affiche la colonne `ville`, Abidjan apparaît quatre fois, car quatre étudiants y habitent. **DISTINCT**, placé juste après SELECT, ne garde qu'un exemplaire de chaque ligne identique."},{"type":"sql","base":"scolarite","titre":"Les villes d'origine, sans doublons","requete":"SELECT DISTINCT ville\nFROM etudiant;","legende":"Enlève DISTINCT puis exécute à nouveau : tu obtiens 8 lignes au lieu de 5."},{"type":"encadre","variante":"attention","titre":"DISTINCT porte sur toute la ligne","contenu":"`SELECT DISTINCT ville, sexe` supprime les lignes où **la ville ET le sexe** sont identiques. Abidjan apparaîtra donc deux fois : une fois avec F, une fois avec M."},{"type":"titre","contenu":"5. Trier avec ORDER BY"},{"type":"texte","contenu":"Sans ORDER BY, l'ordre des lignes n'est **pas garanti** : le SGBD les affiche comme il veut. **ORDER BY** trie le résultat selon une ou plusieurs colonnes, en ordre croissant (**ASC**, par défaut) ou décroissant (**DESC**)."},{"type":"sql","base":"scolarite","titre":"Classement des notes, de la meilleure à la moins bonne","requete":"SELECT matricule, code_matiere, note\nFROM note\nORDER BY note DESC;"},{"type":"sql","base":"scolarite","titre":"Tri sur deux colonnes","requete":"SELECT ville, nom, prenom\nFROM etudiant\nORDER BY ville ASC, nom ASC;","legende":"On trie d'abord par ville ; pour les étudiants de la même ville (Abidjan), on trie ensuite par nom."},{"type":"tableau","titre":"Limiter le nombre de lignes","entetes":["SGBD","Les 3 meilleures notes"],"lignes":[["MySQL, PostgreSQL, SQLite","SELECT … ORDER BY note DESC LIMIT 3;"],["SQL Server, Access","SELECT TOP 3 … ORDER BY note DESC;"],["Oracle","SELECT … ORDER BY note DESC FETCH FIRST 3 ROWS ONLY;"]],"legende":"Le terminal de cette leçon utilise SQLite : c'est donc LIMIT."},{"type":"encadre","variante":"retenir","titre":"À retenir","elements":["Ordre des clauses : `SELECT … FROM … WHERE … GROUP BY … HAVING … ORDER BY …`.","Projection : on liste les colonnes après SELECT, séparées par des virgules ; `*` = toutes.","`AS` renomme une colonne du résultat ; on peut afficher des calculs.","`DISTINCT` supprime les lignes en double ; `ORDER BY col DESC` trie en décroissant (ASC par défaut)."]},{"type":"quiz","question":"Que fait SELECT DISTINCT code_filiere FROM etudiant; ?","options":["Affiche les 8 codes de filière des étudiants","Affiche chaque code de filière une seule fois","Affiche les filières qui n'ont aucun étudiant"],"bonneReponse":1,"explication":"DISTINCT supprime les doublons : on obtient IDA, FCGE et GEC, une fois chacun."},{"type":"quiz","question":"Comment classer les étudiants du plus jeune au plus âgé ?","options":["ORDER BY date_naissance ASC","ORDER BY date_naissance DESC","ORDER BY age"],"bonneReponse":1,"explication":"Le plus jeune est né le plus récemment : il faut la date de naissance la plus grande en premier, donc DESC. La colonne age n'existe pas."},{"type":"titre","contenu":"Exercices d'application"},{"type":"exercice-corrige","niveau":"application","titre":"Application 1 : écrire des requêtes simples","enonce":"Sur la base Scolarité, écris les requêtes suivantes, puis teste-les dans le terminal SQL.","questions":["Le libellé et le coefficient de toutes les matières.","Les matières, de la plus importante (coefficient le plus élevé) à la moins importante.","Les différents codes de matière présents dans la table note.","Le matricule, le code matière et la note de chaque note, avec une colonne « points » égale à la note multipliée par 2."],"langage":"sql","solution":"-- 1\nSELECT libelle, coefficient\nFROM matiere;\n\n-- 2\nSELECT libelle, coefficient\nFROM matiere\nORDER BY coefficient DESC;\n\n-- 3\nSELECT DISTINCT code_matiere\nFROM note;\n\n-- 4\nSELECT matricule, code_matiere, note, note * 2 AS points\nFROM note;","explication":"Question 3 : sans DISTINCT, on obtiendrait 18 lignes (une par note). Avec DISTINCT, on obtient les 4 matières."},{"type":"exercice-corrige","niveau":"application","titre":"Application 2 : trouver l'erreur","enonce":"Chacune de ces requêtes contient une erreur. Trouve-la et corrige-la.","questions":["SELECT nom, prenom, FROM etudiant;","SELECT nom prenom FROM etudiant;","FROM etudiant SELECT nom;","SELECT nom FROM etudiant ORDER BY nom DECROISSANT;"],"langage":"sql","solution":"-- 1 : virgule en trop avant FROM\nSELECT nom, prenom FROM etudiant;\n\n-- 2 : virgule oubliée (prenom devient un alias de nom)\nSELECT nom, prenom FROM etudiant;\n\n-- 3 : SELECT vient toujours avant FROM\nSELECT nom FROM etudiant;\n\n-- 4 : le mot-clé est DESC\nSELECT nom FROM etudiant ORDER BY nom DESC;","explication":"La requête 2 ne provoque pas d'erreur, et c'est ce qui la rend dangereuse : il faut toujours vérifier que le résultat a le bon nombre de colonnes."},{"type":"titre","contenu":"Sujet type BTS"},{"type":"exercice-corrige","niveau":"bts","titre":"Le catalogue d'une quincaillerie","enonce":"Une quincaillerie d'Adjamé gère ses articles dans une base de données. On donne la relation :\n\nARTICLE (ref_article, designation, categorie, prix_unitaire, quantite_stock)\n\nExemple de ligne : ('A012', 'Ciment CPJ 50 kg', 'Maçonnerie', 5500, 120)","questions":["Écris la requête qui affiche la désignation et le prix de tous les articles.","Écris la requête qui affiche les différentes catégories d'articles.","Écris la requête qui affiche la désignation et la valeur du stock (prix × quantité) de chaque article, la colonne calculée étant nommée valeur_stock.","Écris la requête qui affiche les articles du plus cher au moins cher ; pour un même prix, par ordre alphabétique de désignation.","Écris la requête qui affiche les 5 articles les moins chers (préciser le SGBD utilisé)."],"langage":"sql","solution":"-- 1\nSELECT designation, prix_unitaire\nFROM article;\n\n-- 2\nSELECT DISTINCT categorie\nFROM article;\n\n-- 3\nSELECT designation, prix_unitaire * quantite_stock AS valeur_stock\nFROM article;\n\n-- 4\nSELECT *\nFROM article\nORDER BY prix_unitaire DESC, designation ASC;\n\n-- 5 (MySQL)\nSELECT designation, prix_unitaire\nFROM article\nORDER BY prix_unitaire ASC\nLIMIT 5;\n-- (SQL Server : SELECT TOP 5 designation, prix_unitaire FROM article ORDER BY prix_unitaire;)","explication":"Au BTS, chaque requête est notée sur sa logique : bonnes colonnes, bonne table, bon tri. Respecte exactement les colonnes demandées et nomme les colonnes calculées quand l'énoncé le précise."}],"exercice":{"id":"sql-tri-etudiants","titre":"L'annuaire des étudiants","consigne":"Affiche le nom, le prénom et la ville de tous les étudiants, triés par ordre alphabétique du nom.","langage":"sql","base":"scolarite","codeDepart":"-- Nom, prénom et ville, triés par nom\n\n","indice":"SELECT … FROM etudiant ORDER BY nom;","solution":"SELECT nom, prenom, ville\nFROM etudiant\nORDER BY nom;"}},{"slug":"filtrer-avec-where","titre":"WHERE : filtrer les lignes","duree":"30 min","objectifs":["Filtrer les lignes avec WHERE et les opérateurs de comparaison","Combiner des conditions avec AND, OR, NOT et des parenthèses","Utiliser BETWEEN, IN et LIKE","Tester les valeurs absentes avec IS NULL"],"resume":{"duree":"1 min","scenes":[{"type":"titre","titre":"La clause WHERE","sousTitre":"Le résumé en 2 minutes","narration":"Filtrer les lignes avec WHERE, en deux minutes."},{"type":"code","titre":"Garder certaines lignes","lignes":["SELECT nom, prenom","FROM etudiant","WHERE ville = 'Abidjan';"],"etapes":[{"ligne":1,"variables":{"lignes":"8"},"note":"On part des 8 étudiants"},{"ligne":2,"variables":{"lignes":"4"},"note":"On garde ceux d'Abidjan"},{"ligne":0,"variables":{"lignes":"4"},"sortie":"Koné, Kouassi, N'Guessan, Yao","note":"On affiche nom et prénom"}],"narration":"WHERE garde seulement les lignes qui vérifient la condition. Ici, sur les huit étudiants, seuls les quatre qui habitent Abidjan sont affichés."},{"type":"points","titre":"Les opérateurs","points":["=, <>, <, <=, >, >=","AND, OR, NOT","BETWEEN 10 AND 15","IN ('IDA', 'GEC')","LIKE 'K%'"],"narration":"On compare avec égal, différent, inférieur, supérieur. On combine avec AND, OR et NOT. BETWEEN teste un intervalle, IN une liste de valeurs, et LIKE un modèle de texte."},{"type":"comparaison","titre":"LIKE : les jokers","colonnes":[{"nom":"%","texte":"N'importe quelle suite de caractères : 'K%' = commence par K"},{"nom":"_","texte":"Exactement un caractère : 'Ya_' = Yao, Yak…"}],"narration":"Avec LIKE, le pourcentage remplace n'importe quelle suite de caractères, et le tiret bas remplace exactement un caractère."},{"type":"exemple","titre":"Les étudiantes d'Abidjan","situation":"Une association de femmes en informatique organise un atelier à Abidjan et veut inviter les étudiantes de la ville.","langage":"SQL","code":["SELECT nom, prenom","FROM etudiant","WHERE ville = 'Abidjan'","  AND sexe = 'F';"],"resultat":["Koné      | Awa","N'Guessan | Aya"],"narration":"Exemple concret : avec AND, les deux conditions doivent être vraies. On obtient les deux étudiantes qui habitent Abidjan."},{"type":"exemple","titre":"Repérer les étudiants en difficulté","situation":"Le professeur d'anglais veut proposer du soutien aux étudiants qui ont moins de 10.","langage":"SQL","code":["SELECT matricule, note","FROM note","WHERE code_matiere = 'ANG'","  AND note < 10;"],"resultat":["IDA003 | 8.5","FCG002 | 9"],"narration":"Deuxième exemple : on filtre les notes d'anglais inférieures à dix. Deux étudiants sont concernés."},{"type":"defi","question":"Quels prénoms de la base correspondent à prenom LIKE '%a' ?","reponse":"Awa, Moussa, Aya","explication":"%a signifie « se termine par a », quel que soit le début.","narration":"À toi de jouer. Quels prénoms se terminent par la lettre a ?","narrationReponse":"Réponse : Awa, Moussa et Aya. Pourcentage a signifie : se termine par a."}]},"blocs":[{"type":"titre","contenu":"1. Le principe de WHERE"},{"type":"texte","contenu":"La clause **WHERE** se place après FROM. Elle contient une **condition** que le SGBD teste **ligne par ligne** : la ligne est gardée si la condition est vraie, écartée sinon. C'est l'opération de **sélection** (ou restriction) de l'algèbre relationnelle."},{"type":"sql","base":"scolarite","titre":"Les étudiants qui habitent Abidjan","requete":"SELECT nom, prenom, ville\nFROM etudiant\nWHERE ville = 'Abidjan';","legende":"Remplace Abidjan par Bouaké, puis par abidjan (en minuscules) : le texte doit correspondre exactement."},{"type":"titre","contenu":"2. Les opérateurs de comparaison"},{"type":"tableau","entetes":["Opérateur","Signification","Exemple"],"lignes":[["=","égal à","code_filiere = 'IDA'"],["<> (ou !=)","différent de","sexe <> 'M'"],["<, <=","inférieur, inférieur ou égal","note < 10"],[">, >=","supérieur, supérieur ou égal","coefficient >= 2"]]},{"type":"sql","base":"scolarite","titre":"Les notes inférieures à 10","requete":"SELECT matricule, code_matiere, note\nFROM note\nWHERE note < 10\nORDER BY note;","legende":"WHERE se place toujours avant ORDER BY."},{"type":"encadre","variante":"astuce","titre":"Comparer des dates","contenu":"Les dates s'écrivent entre apostrophes au format `'AAAA-MM-JJ'`. Dans ce format, l'ordre alphabétique est aussi l'ordre chronologique : `date_naissance >= '2005-01-01'` donne les étudiants nés en 2005 ou après."},{"type":"titre","contenu":"3. Combiner les conditions : AND, OR, NOT"},{"type":"tableau","entetes":["Opérateur","La ligne est gardée si…","Exemple"],"lignes":[["AND","les deux conditions sont vraies","sexe = 'F' AND ville = 'Abidjan'"],["OR","au moins une condition est vraie","ville = 'Bouaké' OR ville = 'Korhogo'"],["NOT","la condition est fausse","NOT ville = 'Abidjan'"]]},{"type":"sql","base":"scolarite","titre":"Les étudiantes d'Abidjan","requete":"SELECT nom, prenom, ville\nFROM etudiant\nWHERE sexe = 'F' AND ville = 'Abidjan';"},{"type":"encadre","variante":"attention","titre":"AND passe avant OR : mets des parenthèses","contenu":"Comme la multiplication avant l'addition, **AND est évalué avant OR**. `WHERE ville = 'Abidjan' OR ville = 'Bouaké' AND sexe = 'F'` signifie « (Abidjan) OU (Bouaké ET F) » : les garçons d'Abidjan sont gardés ! Pour « les filles d'Abidjan ou de Bouaké », il faut écrire `WHERE (ville = 'Abidjan' OR ville = 'Bouaké') AND sexe = 'F'`."},{"type":"sql","base":"scolarite","titre":"Essaie avec et sans les parenthèses","requete":"SELECT nom, prenom, ville, sexe\nFROM etudiant\nWHERE (ville = 'Abidjan' OR ville = 'Bouaké') AND sexe = 'F';","legende":"Avec les parenthèses : 2 étudiantes. Supprime-les : tu obtiens 4 lignes, dont des garçons."},{"type":"titre","contenu":"4. BETWEEN, IN et LIKE"},{"type":"tableau","entetes":["Opérateur","Rôle","Équivalent"],"lignes":[["note BETWEEN 10 AND 15","Valeur dans un intervalle (bornes incluses)","note >= 10 AND note <= 15"],["ville IN ('Bouaké', 'Korhogo')","Valeur dans une liste","ville = 'Bouaké' OR ville = 'Korhogo'"],["nom LIKE 'K%'","Texte qui correspond à un modèle","Commence par K"],["NOT IN, NOT BETWEEN, NOT LIKE","Le contraire",""]]},{"type":"tableau","titre":"Les modèles de LIKE (sur les prénoms de la base)","entetes":["Modèle","Signification","Prénoms qui correspondent"],"lignes":[["'K%'","commence par K","Kevin"],["'%a'","se termine par a","Awa, Moussa, Aya"],["'%ou%'","contient « ou »","Moussa, Fatou"],["'Y_o'","Y, un seul caractère, puis o","Yao"],["'_____'","exactement 5 caractères","Fatou, Kevin"]],"legende":"Dans SQLite et MySQL, LIKE ne tient pas compte des majuscules : 'k%' trouve aussi Kevin."},{"type":"sql","base":"scolarite","titre":"Teste les trois opérateurs","requete":"SELECT nom, prenom, ville, date_naissance\nFROM etudiant\nWHERE ville IN ('Abidjan', 'Yamoussoukro')\n  AND date_naissance BETWEEN '2005-01-01' AND '2005-12-31'\n  AND prenom LIKE '%a%';","legende":"Les étudiants d'Abidjan ou de Yamoussoukro, nés en 2005, dont le prénom contient un « a ». Modifie chaque condition pour voir son effet."},{"type":"titre","contenu":"5. Les valeurs absentes : IS NULL"},{"type":"texte","contenu":"**NULL** signifie « valeur inconnue ou absente » (par exemple, un étudiant dont on ne connaît pas la ville). Ce n'est ni 0, ni un texte vide. Attention : on ne peut **pas** tester NULL avec `=` ; il faut écrire **`IS NULL`** ou **`IS NOT NULL`**."},{"type":"sql","base":"scolarite","titre":"Un étudiant sans ville","requete":"INSERT INTO etudiant (matricule, nom, prenom, sexe, code_filiere)\nVALUES ('IDA005', 'Kouamé', 'Serge', 'M', 'IDA');\n\nSELECT matricule, nom, prenom, ville\nFROM etudiant\nWHERE ville IS NULL;","legende":"On ajoute d'abord un étudiant sans ville, puis on le retrouve. Remplace IS NULL par = NULL : aucune ligne n'est trouvée !"},{"type":"encadre","variante":"retenir","titre":"À retenir","elements":["`WHERE condition` garde les lignes pour lesquelles la condition est vraie ; il se place après FROM et avant ORDER BY.","Textes et dates entre apostrophes : `'Abidjan'`, `'2005-01-01'`.","AND est évalué avant OR : utilise des **parenthèses**.","`BETWEEN a AND b` (bornes incluses), `IN (liste)`, `LIKE` avec `%` et `_`, `IS NULL`."]},{"type":"quiz","question":"Quelle condition trouve les étudiants dont le nom commence par « Ko » ?","options":["nom = 'Ko%'","nom LIKE 'Ko%'","nom LIKE '%Ko'"],"bonneReponse":1,"explication":"Les jokers ne fonctionnent qu'avec LIKE. '%Ko' signifierait « se termine par Ko »."},{"type":"quiz","question":"note BETWEEN 10 AND 12 garde-t-il une note de 12 ?","options":["Oui, les bornes sont incluses","Non, 12 est exclu"],"bonneReponse":0,"explication":"BETWEEN inclut les deux bornes : c'est équivalent à note >= 10 AND note <= 12."},{"type":"titre","contenu":"Exercices d'application"},{"type":"exercice-corrige","niveau":"application","titre":"Application 1 : traduire en SQL","enonce":"Écris les requêtes suivantes sur la base Scolarité.","questions":["Les étudiants de la filière IDA (nom, prénom).","Les notes comprises entre 12 et 16 (matricule, matière, note).","Les étudiants qui ne sont pas d'Abidjan.","Les notes d'anglais (ANG) inférieures à 10.","Les étudiants dont le nom contient la lettre « u », triés par nom."],"langage":"sql","solution":"-- 1\nSELECT nom, prenom FROM etudiant\nWHERE code_filiere = 'IDA';\n\n-- 2\nSELECT matricule, code_matiere, note FROM note\nWHERE note BETWEEN 12 AND 16;\n\n-- 3\nSELECT * FROM etudiant\nWHERE ville <> 'Abidjan';\n\n-- 4\nSELECT * FROM note\nWHERE code_matiere = 'ANG' AND note < 10;\n\n-- 5\nSELECT * FROM etudiant\nWHERE nom LIKE '%u%'\nORDER BY nom;","explication":"Question 4 : deux conditions qui doivent être vraies en même temps, donc AND. Résultat : la note 8.5 de IDA003 et la note 9 de FCG002."},{"type":"titre","contenu":"Sujet type BTS"},{"type":"exercice-corrige","niveau":"bts","titre":"La gestion des clients d'un opérateur de transfert d'argent","enonce":"Une agence de transfert d'argent utilise la relation suivante :\n\nCLIENT (num_client, nom, prenom, telephone, ville, date_inscription, solde)\n\nLe solde est exprimé en francs CFA. La colonne telephone peut être vide (NULL).","questions":["Affiche les clients de Daloa dont le solde dépasse 100 000 F.","Affiche les clients inscrits au cours de l'année 2025.","Affiche les clients de Man, Daloa ou Gagnoa, triés par ville puis par nom.","Affiche les clients dont le numéro de téléphone n'est pas renseigné.","Affiche les clients dont le numéro commence par 07, avec un solde compris entre 5 000 et 50 000 F.","Explique pourquoi la requête suivante ne donne pas le résultat attendu « clients de Man ou Daloa ayant un solde nul » :\nSELECT * FROM client WHERE ville = 'Man' OR ville = 'Daloa' AND solde = 0;"],"langage":"sql","solution":"-- 1\nSELECT * FROM client\nWHERE ville = 'Daloa' AND solde > 100000;\n\n-- 2\nSELECT * FROM client\nWHERE date_inscription BETWEEN '2025-01-01' AND '2025-12-31';\n\n-- 3\nSELECT * FROM client\nWHERE ville IN ('Man', 'Daloa', 'Gagnoa')\nORDER BY ville, nom;\n\n-- 4\nSELECT * FROM client\nWHERE telephone IS NULL;\n\n-- 5\nSELECT * FROM client\nWHERE telephone LIKE '07%'\n  AND solde BETWEEN 5000 AND 50000;\n\n-- 6\n-- AND est évalué avant OR : la requête est comprise comme\n--   ville = 'Man' OR (ville = 'Daloa' AND solde = 0)\n-- Elle affiche donc TOUS les clients de Man, quel que soit leur solde.\n-- Correction :\nSELECT * FROM client\nWHERE (ville = 'Man' OR ville = 'Daloa') AND solde = 0;","explication":"La question 6 est un grand classique : sa réponse doit nommer la cause (priorité de AND sur OR) et proposer la correction avec des parenthèses. Note aussi que les montants s'écrivent sans espace (100000) et sans « F »."}],"exercice":{"id":"sql-nes-en-2005","titre":"Les étudiants nés en 2005","consigne":"Affiche le nom, le prénom et la date de naissance des étudiants nés en 2005.","langage":"sql","base":"scolarite","codeDepart":"-- Étudiants nés en 2005\n\n","indice":"WHERE date_naissance BETWEEN '2005-01-01' AND '2005-12-31'","solution":"SELECT nom, prenom, date_naissance\nFROM etudiant\nWHERE date_naissance BETWEEN '2005-01-01' AND '2005-12-31';"}},{"slug":"fonctions-d-agregation","titre":"Les fonctions d'agrégation : compter, additionner, calculer une moyenne","duree":"25 min","objectifs":["Utiliser COUNT, SUM, AVG, MIN et MAX","Combiner une fonction d'agrégation avec WHERE","Arrondir un résultat avec ROUND","Distinguer COUNT(*), COUNT(colonne) et COUNT(DISTINCT colonne)"],"resume":{"duree":"1 min 30","scenes":[{"type":"titre","titre":"Les fonctions d'agrégation","sousTitre":"Le résumé en 2 minutes","narration":"Les fonctions d'agrégation en SQL, en deux minutes."},{"type":"points","titre":"5 fonctions à connaître","points":["COUNT : compter","SUM : additionner","AVG : moyenne","MIN et MAX : plus petite et plus grande valeur"],"narration":"Cinq fonctions résument plusieurs lignes en une seule valeur : COUNT compte, SUM additionne, AVG calcule la moyenne, MIN et MAX donnent la plus petite et la plus grande valeur."},{"type":"code","titre":"Les notes d'algorithmique","lignes":["SELECT COUNT(*), AVG(note)","FROM note","WHERE code_matiere = 'ALGO';"],"etapes":[{"ligne":1,"variables":{"lignes":"18"},"note":"18 notes dans la table"},{"ligne":2,"variables":{"lignes":"4"},"note":"WHERE garde les 4 notes d'ALGO"},{"ligne":0,"variables":{"lignes":"1"},"sortie":"4 | 13.25","note":"Les 4 lignes deviennent une seule"}],"narration":"WHERE filtre d'abord les lignes : il reste les quatre notes d'algorithmique. Puis les fonctions les résument en une seule ligne : quatre notes, moyenne treize virgule vingt-cinq."},{"type":"comparaison","titre":"Les 3 façons de compter","colonnes":[{"nom":"COUNT(*)","texte":"Toutes les lignes"},{"nom":"COUNT(ville)","texte":"Les lignes où ville n'est pas NULL"},{"nom":"COUNT(DISTINCT ville)","texte":"Le nombre de villes différentes"}],"narration":"COUNT étoile compte toutes les lignes. COUNT d'une colonne ignore les valeurs NULL. Et COUNT DISTINCT compte les valeurs différentes."},{"type":"exemple","titre":"Le bilan de l'algorithmique","situation":"Après l'examen, le professeur d'algorithmique veut le nombre de copies, la moyenne et la meilleure note.","langage":"SQL","code":["SELECT COUNT(*), AVG(note),","       MAX(note)","FROM note","WHERE code_matiere = 'ALGO';"],"resultat":["COUNT | AVG   | MAX","4     | 13.25 | 17"],"narration":"Exemple concret : WHERE garde d'abord les quatre notes d'algorithmique, puis les fonctions les résument : quatre notes, moyenne treize virgule vingt-cinq, meilleure note dix-sept."},{"type":"exemple","titre":"L'effectif de la filière IDA","situation":"Pour commander les supports de cours, la scolarité doit savoir combien d'étudiants sont en IDA.","langage":"SQL","code":["SELECT COUNT(*) AS effectif","FROM etudiant","WHERE code_filiere = 'IDA';"],"resultat":["effectif","4"],"narration":"Deuxième exemple : COUNT étoile compte les lignes retenues. Il y a quatre étudiants en IDA."},{"type":"defi","question":"Que renvoie cette requête ?","code":["SELECT SUM(coefficient)","FROM matiere;"],"reponse":"9","explication":"3 + 3 + 1 + 2 = 9 : la somme des coefficients des 4 matières.","narration":"À toi de jouer. Les coefficients sont trois, trois, un et deux. Que renvoie cette requête ?","narrationReponse":"Réponse : neuf, la somme des quatre coefficients."}]},"blocs":[{"type":"titre","contenu":"1. Résumer plusieurs lignes en une seule"},{"type":"texte","contenu":"Jusqu'ici, nos requêtes affichaient des lignes de la table. Les **fonctions d'agrégation** font autre chose : elles prennent **toutes les lignes** retenues et les **résument** en une seule valeur. C'est ce qu'on utilise pour répondre aux questions « combien ? », « quel total ? », « quelle moyenne ? »."},{"type":"tableau","entetes":["Fonction","Rôle","Exemple"],"lignes":[["COUNT(*)","Nombre de lignes","Combien d'étudiants ?"],["SUM(colonne)","Somme des valeurs","Total des ventes"],["AVG(colonne)","Moyenne des valeurs","Moyenne des notes"],["MIN(colonne)","Plus petite valeur","La note la plus basse"],["MAX(colonne)","Plus grande valeur","La date d'inscription la plus récente"]]},{"type":"sql","base":"scolarite","titre":"Statistiques sur toutes les notes","requete":"SELECT COUNT(*) AS nombre_notes,\n       AVG(note) AS moyenne,\n       MIN(note) AS plus_basse,\n       MAX(note) AS plus_haute\nFROM note;","legende":"Une seule ligne de résultat, même si la table contient 18 notes."},{"type":"titre","contenu":"2. Avec WHERE : filtrer d'abord, résumer ensuite"},{"type":"texte","contenu":"Le SGBD applique **d'abord** WHERE pour choisir les lignes, **puis** calcule la fonction sur les lignes restantes. Pour obtenir la moyenne en algorithmique, on garde les notes d'ALGO, puis on fait la moyenne."},{"type":"sql","base":"scolarite","titre":"La moyenne de la classe en algorithmique","requete":"SELECT AVG(note) AS moyenne_algo\nFROM note\nWHERE code_matiere = 'ALGO';","legende":"Calcul : (15 + 9 + 17 + 12) / 4 = 13,25. Remplace ALGO par BD ou ANG."},{"type":"sql","base":"scolarite","titre":"Combien d'étudiantes ?","requete":"SELECT COUNT(*) AS nombre_etudiantes\nFROM etudiant\nWHERE sexe = 'F';"},{"type":"titre","contenu":"3. Arrondir avec ROUND"},{"type":"texte","contenu":"Une moyenne donne souvent beaucoup de décimales (12,1666…). **ROUND(valeur, n)** arrondit à n chiffres après la virgule."},{"type":"sql","base":"scolarite","titre":"Moyenne générale arrondie","requete":"SELECT AVG(note) AS brute,\n       ROUND(AVG(note), 2) AS arrondie\nFROM note;"},{"type":"titre","contenu":"4. Les trois façons de compter"},{"type":"tableau","entetes":["Écriture","Ce qui est compté"],"lignes":[["COUNT(*)","Toutes les lignes"],["COUNT(colonne)","Les lignes où la colonne n'est pas NULL"],["COUNT(DISTINCT colonne)","Le nombre de valeurs différentes (sans NULL)"]]},{"type":"sql","base":"scolarite","titre":"Comparer les trois","requete":"INSERT INTO etudiant (matricule, nom, prenom, sexe, code_filiere)\nVALUES ('IDA005', 'Kouamé', 'Serge', 'M', 'IDA');\n\nSELECT COUNT(*) AS etudiants,\n       COUNT(ville) AS villes_renseignees,\n       COUNT(DISTINCT ville) AS villes_differentes\nFROM etudiant;","legende":"On ajoute un étudiant sans ville : 9 étudiants, 8 villes renseignées, 5 villes différentes."},{"type":"encadre","variante":"attention","titre":"Une erreur fréquente","contenu":"On ne peut pas mélanger une colonne « normale » et une fonction d'agrégation : `SELECT nom, MAX(note) FROM …` n'a pas de sens, car il y a plusieurs noms mais un seul maximum. MySQL et SQL Server refusent cette requête (SQLite l'accepte mais le résultat est trompeur). Pour obtenir un résultat **par** étudiant ou **par** matière, il faut **GROUP BY**, vu au chapitre suivant."},{"type":"encadre","variante":"retenir","titre":"À retenir","elements":["`COUNT`, `SUM`, `AVG`, `MIN`, `MAX` résument toutes les lignes retenues en une seule valeur.","WHERE est appliqué **avant** le calcul.","`ROUND(valeur, 2)` arrondit à 2 décimales.","`COUNT(*)` compte les lignes, `COUNT(col)` ignore les NULL, `COUNT(DISTINCT col)` compte les valeurs différentes."]},{"type":"quiz","question":"Quelle requête donne le nombre de villes différentes des étudiants ?","options":["SELECT COUNT(ville) FROM etudiant;","SELECT COUNT(DISTINCT ville) FROM etudiant;","SELECT DISTINCT COUNT(ville) FROM etudiant;"],"bonneReponse":1,"explication":"COUNT(DISTINCT ville) compte les villes différentes (5). COUNT(ville) compte les 8 étudiants dont la ville est renseignée."},{"type":"quiz","question":"Que renvoie SELECT MAX(date_naissance) FROM etudiant; ?","options":["La date de naissance de l'étudiant le plus âgé","La date de naissance de l'étudiant le plus jeune"],"bonneReponse":1,"explication":"La date la plus grande est la plus récente : c'est celle de l'étudiant le plus jeune (2006-02-11, Mariam Ouattara)."},{"type":"titre","contenu":"Exercices d'application"},{"type":"exercice-corrige","niveau":"application","titre":"Application 1 : statistiques de la scolarité","enonce":"Écris une requête pour chaque question, puis note le résultat obtenu dans le terminal.","questions":["Le nombre total d'étudiants.","Le nombre d'étudiants de la filière IDA.","La meilleure note obtenue en Base de données (BD).","La somme des coefficients de toutes les matières.","La moyenne des notes d'anglais, arrondie à 2 décimales."],"langage":"sql","solution":"-- 1 → 8\nSELECT COUNT(*) FROM etudiant;\n\n-- 2 → 4\nSELECT COUNT(*) FROM etudiant\nWHERE code_filiere = 'IDA';\n\n-- 3 → 16\nSELECT MAX(note) FROM note\nWHERE code_matiere = 'BD';\n\n-- 4 → 9\nSELECT SUM(coefficient) FROM matiere;\n\n-- 5 → 11.75\nSELECT ROUND(AVG(note), 2) FROM note\nWHERE code_matiere = 'ANG';","explication":"Question 5 : il y a 8 notes d'anglais, dont la somme est 94 ; 94 / 8 = 11,75."},{"type":"titre","contenu":"Sujet type BTS"},{"type":"exercice-corrige","niveau":"bts","titre":"Les ventes d'une boutique de téléphones","enonce":"Une boutique de téléphones de Cocody enregistre ses ventes dans la relation :\n\nVENTE (num_vente, date_vente, ref_produit, quantite, prix_unitaire, mode_paiement)\n\nmode_paiement vaut 'Espèces', 'Wave' ou 'Orange Money'.","questions":["Écris la requête qui donne le nombre total de ventes enregistrées.","Écris la requête qui donne le chiffre d'affaires total (somme de quantite × prix_unitaire).","Écris la requête qui donne le chiffre d'affaires du mois de mars 2026.","Écris la requête qui donne le prix unitaire le plus élevé et le plus bas pratiqués.","Écris la requête qui donne le nombre de produits différents vendus.","Écris la requête qui donne le nombre de ventes payées par Wave ou Orange Money."],"langage":"sql","solution":"-- 1\nSELECT COUNT(*) AS nombre_ventes\nFROM vente;\n\n-- 2\nSELECT SUM(quantite * prix_unitaire) AS chiffre_affaires\nFROM vente;\n\n-- 3\nSELECT SUM(quantite * prix_unitaire) AS ca_mars_2026\nFROM vente\nWHERE date_vente BETWEEN '2026-03-01' AND '2026-03-31';\n\n-- 4\nSELECT MAX(prix_unitaire) AS prix_max, MIN(prix_unitaire) AS prix_min\nFROM vente;\n\n-- 5\nSELECT COUNT(DISTINCT ref_produit) AS produits_vendus\nFROM vente;\n\n-- 6\nSELECT COUNT(*) AS ventes_mobile_money\nFROM vente\nWHERE mode_paiement IN ('Wave', 'Orange Money');","explication":"Question 2 : on peut faire un calcul à l'intérieur d'une fonction d'agrégation. SUM(quantite) * SUM(prix_unitaire) serait faux : il faut multiplier ligne par ligne, puis additionner."}],"exercice":{"id":"sql-stats-algo","titre":"Les statistiques d'algorithmique","consigne":"Affiche, pour la matière ALGO : le nombre de notes, la moyenne, la note la plus basse et la note la plus haute (4 colonnes, dans cet ordre).","langage":"sql","base":"scolarite","codeDepart":"-- Nombre, moyenne, minimum et maximum des notes d'ALGO\n\n","indice":"SELECT COUNT(*), AVG(note), MIN(note), MAX(note) FROM note WHERE …","solution":"SELECT COUNT(*) AS nombre, AVG(note) AS moyenne, MIN(note) AS minimum, MAX(note) AS maximum\nFROM note\nWHERE code_matiere = 'ALGO';"}}]$contenu$::jsonb)
on conflict (cle) do update set lecons = excluded.lecons, mis_a_jour = now();

insert into public.contenu_premium (cle, lecons) values ('base-de-donnees/jointures-et-regroupements', $contenu$[{"slug":"jointure-interne","titre":"La jointure interne : relier plusieurs tables","duree":"30 min","objectifs":["Comprendre pourquoi on a besoin d'une jointure","Écrire une jointure avec INNER JOIN … ON","Utiliser des alias de tables","Joindre trois tables ou plus"],"resume":{"duree":"1 min 30","scenes":[{"type":"titre","titre":"La jointure","sousTitre":"Le résumé en 2 minutes","narration":"La jointure interne en SQL, en deux minutes."},{"type":"comparaison","titre":"Le problème","colonnes":[{"nom":"Table etudiant","texte":"Contient le code de la filière : 'IDA'"},{"nom":"Table filiere","texte":"Contient le libellé : 'Informatique Développeur d'Application'"}],"narration":"Grâce à la normalisation, chaque information n'est écrite qu'une fois. La table étudiant contient seulement le code de la filière ; son libellé est dans la table filière. Pour afficher les deux ensemble, il faut relier les tables : c'est la jointure."},{"type":"code","titre":"Relier par la clé","lignes":["SELECT e.nom, f.libelle","FROM etudiant e","JOIN filiere f","  ON e.code_filiere = f.code_filiere;"],"etapes":[{"ligne":1,"variables":{"tables":"etudiant"}},{"ligne":2,"variables":{"tables":"etudiant + filiere"},"note":"On ajoute la table filiere"},{"ligne":3,"variables":{"tables":"etudiant + filiere"},"note":"Clé étrangère = clé primaire"},{"ligne":0,"variables":{"tables":"etudiant + filiere"},"sortie":"Koné | Informatique Développeur…"}],"narration":"On écrit FROM la première table, JOIN la deuxième, et après ON, la condition de jointure : la clé étrangère est égale à la clé primaire. Chaque étudiant est alors associé à sa filière."},{"type":"points","titre":"À ne pas oublier","points":["Une condition ON par table ajoutée","Préfixer les colonnes communes","Sans condition : produit cartésien !"],"narration":"Il faut une condition ON pour chaque table ajoutée, préfixer les colonnes qui existent dans plusieurs tables, et ne jamais oublier la condition, sinon on obtient toutes les combinaisons possibles."},{"type":"exemple","titre":"Les étudiants de Bouaké et leur filière","situation":"Le délégué de Bouaké veut le prénom de chaque étudiant de sa ville, avec le nom complet de sa filière.","langage":"SQL","code":["SELECT e.prenom, f.libelle","FROM etudiant e","JOIN filiere f","  ON e.code_filiere = f.code_filiere","WHERE e.ville = 'Bouaké';"],"resultat":["Moussa | Informatique","       | Développeur d'Application"],"narration":"Exemple concret : le prénom est dans la table étudiant, le libellé dans la table filière. La jointure relie les deux par le code filière."},{"type":"exemple","titre":"Le relevé de notes de Yao","situation":"Yao Kouassi (IDA003) demande son relevé : libellé de chaque matière et note. Trois tables sont nécessaires.","langage":"SQL","code":["SELECT m.libelle, n.note","FROM note n","JOIN matiere m","  ON n.code_matiere = m.code_matiere","WHERE n.matricule = 'IDA003';"],"resultat":["Algorithmique   | 17","Base de données | 16","Anglais         | 8.5"],"narration":"Deuxième exemple : le relevé de Yao. La note est dans la table note, le libellé de la matière dans la table matière : on les relie par le code matière."},{"type":"defi","question":"8 étudiants, 3 filières. Combien de lignes si on oublie la condition de jointure ?","code":["SELECT e.nom, f.libelle","FROM etudiant e, filiere f;"],"reponse":"24 lignes","explication":"Produit cartésien : 8 × 3 = 24. Chaque étudiant est associé à toutes les filières.","narration":"À toi de jouer. Huit étudiants, trois filières, et on a oublié la condition de jointure. Combien de lignes ?","narrationReponse":"Réponse : vingt-quatre lignes. C'est le produit cartésien, huit fois trois : chaque étudiant est associé à toutes les filières."}]},"blocs":[{"type":"titre","contenu":"1. Pourquoi joindre des tables ?"},{"type":"texte","contenu":"Une base normalisée découpe l'information en plusieurs tables reliées par des **clés étrangères**. C'est efficace pour stocker, mais pour **afficher**, on a souvent besoin de colonnes venant de plusieurs tables. Exemple : la table `etudiant` contient `code_filiere = 'IDA'`, mais le libellé « Informatique Développeur d'Application » est dans la table `filiere`."},{"type":"texte","contenu":"La **jointure** reconstitue l'information : pour chaque ligne de la première table, le SGBD cherche la ligne de la deuxième table dont la **clé primaire** est égale à la **clé étrangère**, et colle les deux lignes côte à côte."},{"type":"titre","contenu":"2. La syntaxe INNER JOIN … ON"},{"type":"code","langage":"sql","code":"SELECT colonnes\nFROM table1\nINNER JOIN table2 ON table1.cle_etrangere = table2.cle_primaire;","legende":"`INNER JOIN` peut s'écrire simplement `JOIN`."},{"type":"sql","base":"scolarite","titre":"Chaque étudiant avec le libellé de sa filière","requete":"SELECT etudiant.nom, etudiant.prenom, filiere.libelle\nFROM etudiant\nINNER JOIN filiere ON etudiant.code_filiere = filiere.code_filiere;"},{"type":"encadre","variante":"attention","titre":"Les colonnes « ambiguës »","contenu":"La colonne `code_filiere` existe dans les deux tables. Si on écrit simplement `SELECT code_filiere`, le SGBD ne sait pas laquelle prendre et renvoie une erreur « ambiguous column ». Il faut **préfixer** par le nom de la table : `etudiant.code_filiere`."},{"type":"titre","contenu":"3. Les alias de tables"},{"type":"texte","contenu":"Répéter `etudiant.` et `filiere.` devient vite long. On donne à chaque table un **alias** court juste après son nom dans FROM ou JOIN, puis on l'utilise partout dans la requête."},{"type":"sql","base":"scolarite","titre":"La même requête avec des alias","requete":"SELECT e.nom, e.prenom, f.libelle AS filiere\nFROM etudiant e\nJOIN filiere f ON e.code_filiere = f.code_filiere\nWHERE e.ville = 'Abidjan'\nORDER BY e.nom;","legende":"On peut ajouter WHERE et ORDER BY comme d'habitude, après les jointures."},{"type":"titre","contenu":"4. Joindre trois tables"},{"type":"texte","contenu":"Pour afficher un **relevé de notes** (nom de l'étudiant, libellé de la matière, note), il faut trois tables : `etudiant`, `note` et `matiere`. La table `note` est au milieu : elle contient les deux clés étrangères. On ajoute **un JOIN et une condition ON par table**."},{"type":"tableau","entetes":["Table","Relie à","Condition"],"lignes":[["note","etudiant","n.matricule = e.matricule"],["note","matiere","n.code_matiere = m.code_matiere"]]},{"type":"sql","base":"scolarite","titre":"Le relevé de notes d'Awa Koné","requete":"SELECT e.nom, e.prenom, m.libelle, m.coefficient, n.note\nFROM note n\nJOIN etudiant e ON n.matricule = e.matricule\nJOIN matiere m ON n.code_matiere = m.code_matiere\nWHERE e.matricule = 'IDA001';","legende":"Remplace IDA001 par IDA003 ou FCG001. Enlève la ligne WHERE pour voir le relevé de toute l'école."},{"type":"encadre","variante":"astuce","titre":"Méthode pour toute question de jointure","elements":["Liste les **colonnes** demandées et note de quelle table vient chacune.","Ajoute les **tables intermédiaires** nécessaires pour relier ces tables (suis les flèches du schéma relationnel).","Écris **une condition ON par table ajoutée** : clé étrangère = clé primaire.","Ajoute enfin WHERE, puis ORDER BY."]},{"type":"titre","contenu":"5. L'ancienne syntaxe et le produit cartésien"},{"type":"texte","contenu":"Tu rencontreras aussi, dans les anciens sujets et corrigés, la jointure écrite **dans le WHERE** : on liste les tables après FROM, séparées par des virgules, et on met la condition de jointure dans WHERE. Le résultat est le même."},{"type":"code","langage":"sql","code":"SELECT e.nom, f.libelle\nFROM etudiant e, filiere f\nWHERE e.code_filiere = f.code_filiere;"},{"type":"sql","base":"scolarite","titre":"Sans condition de jointure : le produit cartésien","requete":"SELECT e.nom, f.libelle\nFROM etudiant e, filiere f;","legende":"8 étudiants × 3 filières = 24 lignes : chaque étudiant est associé à toutes les filières. C'est faux ! Ajoute la condition WHERE pour revenir à 8 lignes."},{"type":"encadre","variante":"retenir","titre":"À retenir","elements":["La jointure relie deux tables par **clé étrangère = clé primaire**.","`FROM t1 JOIN t2 ON t1.fk = t2.pk` ; alias : `FROM etudiant e`.","Préfixe les colonnes présentes dans plusieurs tables (`e.code_filiere`).","**n tables → n − 1 conditions de jointure** ; sans condition, on obtient le produit cartésien."]},{"type":"quiz","question":"Pour joindre 4 tables, combien faut-il de conditions de jointure ?","options":["2","3","4"],"bonneReponse":1,"explication":"Il faut n − 1 conditions pour n tables : chaque table ajoutée après la première est reliée par une condition."},{"type":"quiz","question":"Que signifie l'erreur « ambiguous column name: matricule » ?","options":["La colonne matricule n'existe pas","La colonne matricule existe dans plusieurs tables de la requête","La colonne matricule contient des doublons"],"bonneReponse":1,"explication":"Il faut préciser la table : e.matricule ou n.matricule."},{"type":"titre","contenu":"Exercices d'application"},{"type":"exercice-corrige","niveau":"application","titre":"Application 1 : écrire des jointures","enonce":"Écris les requêtes suivantes sur la base Scolarité.","questions":["Le nom et le prénom des étudiants de la filière « Gestion Commerciale » (en utilisant le libellé, pas le code).","Le matricule, le libellé de la matière et la note de toutes les notes supérieures ou égales à 15.","Le nom de l'étudiant, le libellé de sa filière, le libellé de la matière et la note, pour les notes d'anglais, triées par note décroissante."],"langage":"sql","solution":"-- 1\nSELECT e.nom, e.prenom\nFROM etudiant e\nJOIN filiere f ON e.code_filiere = f.code_filiere\nWHERE f.libelle = 'Gestion Commerciale';\n\n-- 2\nSELECT n.matricule, m.libelle, n.note\nFROM note n\nJOIN matiere m ON n.code_matiere = m.code_matiere\nWHERE n.note >= 15;\n\n-- 3 (4 tables → 3 conditions)\nSELECT e.nom, f.libelle AS filiere, m.libelle AS matiere, n.note\nFROM note n\nJOIN etudiant e ON n.matricule = e.matricule\nJOIN filiere f  ON e.code_filiere = f.code_filiere\nJOIN matiere m  ON n.code_matiere = m.code_matiere\nWHERE n.code_matiere = 'ANG'\nORDER BY n.note DESC;","explication":"Question 1 : le libellé est dans filiere, les noms dans etudiant : il faut les deux tables, même si on n'affiche que des colonnes d'etudiant."},{"type":"titre","contenu":"Sujet type BTS"},{"type":"exercice-corrige","niveau":"bts","titre":"La gestion des commandes d'un grossiste","enonce":"Un grossiste de Yopougon utilise le schéma relationnel suivant :\n\nCLIENT (num_client, nom_client, ville)\nCOMMANDE (num_cde, date_cde, #num_client)\nPRODUIT (ref_produit, designation, prix_unitaire)\nLIGNE_COMMANDE (#num_cde, #ref_produit, quantite)","questions":["Identifie les clés étrangères et la table qu'elles référencent.","Affiche le numéro et la date des commandes passées par le client « Boutique Bénédiction ».","Affiche la désignation et la quantité des produits de la commande n° 1045.","Affiche le nom des clients de Bouaké ayant commandé du « Riz parfumé 25 kg » (sans doublons).","Affiche, pour chaque ligne de la commande n° 1045, la désignation, la quantité, le prix unitaire et le montant de la ligne."],"langage":"sql","solution":"-- 1\n-- COMMANDE.num_client         → CLIENT(num_client)\n-- LIGNE_COMMANDE.num_cde      → COMMANDE(num_cde)\n-- LIGNE_COMMANDE.ref_produit  → PRODUIT(ref_produit)\n\n-- 2\nSELECT co.num_cde, co.date_cde\nFROM commande co\nJOIN client cl ON co.num_client = cl.num_client\nWHERE cl.nom_client = 'Boutique Bénédiction';\n\n-- 3\nSELECT p.designation, l.quantite\nFROM ligne_commande l\nJOIN produit p ON l.ref_produit = p.ref_produit\nWHERE l.num_cde = 1045;\n\n-- 4 (4 tables → 3 conditions)\nSELECT DISTINCT cl.nom_client\nFROM client cl\nJOIN commande co      ON co.num_client = cl.num_client\nJOIN ligne_commande l ON l.num_cde = co.num_cde\nJOIN produit p        ON p.ref_produit = l.ref_produit\nWHERE cl.ville = 'Bouaké'\n  AND p.designation = 'Riz parfumé 25 kg';\n\n-- 5\nSELECT p.designation, l.quantite, p.prix_unitaire,\n       l.quantite * p.prix_unitaire AS montant\nFROM ligne_commande l\nJOIN produit p ON l.ref_produit = p.ref_produit\nWHERE l.num_cde = 1045;","explication":"Question 3 : inutile de joindre COMMANDE, car le numéro de commande est déjà dans LIGNE_COMMANDE. Joindre une table dont on n'a pas besoin n'est pas faux, mais un correcteur apprécie une requête sans table inutile. Question 4 : DISTINCT évite d'afficher plusieurs fois un client qui a commandé ce riz plusieurs fois."}],"exercice":{"id":"sql-releve-ida","titre":"Le relevé de notes de la filière IDA","consigne":"Affiche le nom, le prénom, le libellé de la matière et la note des étudiants de la filière IDA, triés par nom puis par libellé de matière.","langage":"sql","base":"scolarite","codeDepart":"-- Relevé des notes de la filière IDA (3 tables)\n\n","indice":"FROM note n JOIN etudiant e ON … JOIN matiere m ON … WHERE e.code_filiere = 'IDA' ORDER BY e.nom, m.libelle","solution":"SELECT e.nom, e.prenom, m.libelle, n.note\nFROM note n\nJOIN etudiant e ON n.matricule = e.matricule\nJOIN matiere m ON n.code_matiere = m.code_matiere\nWHERE e.code_filiere = 'IDA'\nORDER BY e.nom, m.libelle;"}},{"slug":"jointure-externe","titre":"La jointure externe : garder les lignes sans correspondance","duree":"25 min","objectifs":["Comprendre ce que la jointure interne fait disparaître","Écrire une jointure externe avec LEFT JOIN","Trouver les lignes « sans correspondance » avec IS NULL","Placer correctement une condition dans ON ou dans WHERE"],"resume":{"duree":"1 min 30","scenes":[{"type":"titre","titre":"LEFT JOIN","sousTitre":"Le résumé en 2 minutes","narration":"La jointure externe, en deux minutes."},{"type":"comparaison","titre":"Interne ou externe ?","colonnes":[{"nom":"INNER JOIN","texte":"Seulement les lignes qui ont une correspondance"},{"nom":"LEFT JOIN","texte":"Toutes les lignes de gauche, avec NULL s'il n'y a pas de correspondance"}],"narration":"La jointure interne ne garde que les lignes qui ont une correspondance dans l'autre table. La jointure externe gauche garde toutes les lignes de la table de gauche, et met NULL quand il n'y a pas de correspondance."},{"type":"code","titre":"Trouver ce qui manque","lignes":["SELECT f.libelle","FROM filiere f","LEFT JOIN etudiant e ON e.code_filiere = f.code_filiere","WHERE e.matricule IS NULL;"],"etapes":[{"ligne":1,"variables":{"filieres":"toutes"}},{"ligne":2,"variables":{"filieres":"toutes","etudiant":"ou NULL"},"note":"Chaque filière garde sa ligne"},{"ligne":3,"variables":{"filieres":"sans étudiant"},"sortie":"Les filières vides","note":"On garde les NULL"}],"narration":"Pour trouver ce qui n'existe pas, par exemple les filières sans étudiant, on fait un LEFT JOIN puis on garde les lignes où la colonne de droite est NULL."},{"type":"exemple","titre":"Qui n'a pas composé en BD ?","situation":"Le jury veut la liste des étudiants qui n'ont aucune note de Base de données.","langage":"SQL","code":["SELECT e.prenom","FROM etudiant e","LEFT JOIN note n","  ON n.matricule = e.matricule","  AND n.code_matiere = 'BD'","WHERE n.matricule IS NULL;"],"resultat":["Aya","Ibrahim","Mariam","Kevin"],"narration":"Exemple concret : LEFT JOIN garde tous les étudiants. Ceux qui n'ont pas de note de BD reçoivent NULL, et WHERE IS NULL les sélectionne."},{"type":"exemple","titre":"Les clients qui n'ont jamais commandé","situation":"Un grossiste veut relancer les clients inscrits qui n'ont encore jamais passé de commande.","langage":"SQL","code":["SELECT c.nom_client","FROM client c","LEFT JOIN commande co","  ON co.num_client = c.num_client","WHERE co.num_cde IS NULL;"],"resultat":["Les clients","sans aucune commande"],"narration":"Deuxième exemple : la même méthode pour un grossiste. LEFT JOIN, puis IS NULL : on obtient les clients qui n'ont jamais commandé."},{"type":"defi","question":"Pour lister les produits jamais vendus, quelle jointure et quelle condition ?","reponse":"LEFT JOIN + IS NULL","explication":"produit LEFT JOIN vente … WHERE vente.num_vente IS NULL","narration":"À toi de jouer. Pour lister les produits jamais vendus, quelle jointure et quelle condition utiliser ?","narrationReponse":"Réponse : une jointure externe gauche, LEFT JOIN, depuis la table produit, puis la condition IS NULL sur la table des ventes."}]},"blocs":[{"type":"titre","contenu":"1. Ce que la jointure interne fait disparaître"},{"type":"texte","contenu":"La jointure interne ne garde que les lignes qui ont une **correspondance** dans les deux tables. Une filière qui n'a encore **aucun** étudiant n'apparaît donc pas dans le résultat. Pour le voir, ajoutons une nouvelle filière, « Ressources Humaines et Communication », sans étudiant :"},{"type":"sql","base":"scolarite","titre":"Jointure interne : la nouvelle filière a disparu","requete":"INSERT INTO filiere VALUES ('RHC', 'Ressources Humaines et Communication');\n\nSELECT f.libelle, e.nom, e.prenom\nFROM filiere f\nINNER JOIN etudiant e ON e.code_filiere = f.code_filiere;","legende":"8 lignes : la filière RHC n'est pas affichée, car aucun étudiant ne lui correspond."},{"type":"titre","contenu":"2. LEFT JOIN : garder toutes les lignes de gauche"},{"type":"texte","contenu":"Avec **LEFT JOIN** (ou LEFT OUTER JOIN), **toutes** les lignes de la table de gauche (celle écrite dans FROM) sont gardées. Quand une ligne n'a pas de correspondance, les colonnes de la table de droite sont remplies avec **NULL**."},{"type":"sql","base":"scolarite","titre":"Jointure externe : toutes les filières","requete":"INSERT INTO filiere VALUES ('RHC', 'Ressources Humaines et Communication');\n\nSELECT f.libelle, e.nom, e.prenom\nFROM filiere f\nLEFT JOIN etudiant e ON e.code_filiere = f.code_filiere;","legende":"9 lignes : la filière RHC apparaît, avec NULL dans les colonnes nom et prénom."},{"type":"tableau","entetes":["Jointure","Lignes gardées"],"lignes":[["INNER JOIN","Seulement les lignes qui ont une correspondance des deux côtés"],["LEFT JOIN","Toutes les lignes de la table de gauche (+ NULL si pas de correspondance)"],["RIGHT JOIN","Toutes les lignes de la table de droite (rarement utilisé : on inverse les tables et on fait un LEFT JOIN)"],["FULL OUTER JOIN","Toutes les lignes des deux tables (n'existe pas en MySQL)"]]},{"type":"titre","contenu":"3. Trouver ce qui n'existe pas"},{"type":"texte","contenu":"C'est l'usage le plus fréquent du LEFT JOIN, et une question très classique d'examen : « les filières **sans** étudiant », « les clients qui n'ont **jamais** commandé », « les produits **jamais** vendus ». On fait un LEFT JOIN, puis on garde les lignes où la clé de la table de droite **IS NULL**."},{"type":"sql","base":"scolarite","titre":"Les filières sans aucun étudiant","requete":"INSERT INTO filiere VALUES ('RHC', 'Ressources Humaines et Communication');\n\nSELECT f.code_filiere, f.libelle\nFROM filiere f\nLEFT JOIN etudiant e ON e.code_filiere = f.code_filiere\nWHERE e.matricule IS NULL;"},{"type":"titre","contenu":"4. Une condition dans ON ou dans WHERE ?"},{"type":"texte","contenu":"Question : afficher **tous** les étudiants avec leur note d'algorithmique, y compris ceux qui n'en ont pas (les étudiants de FCGE et GEC ne suivent pas l'ALGO). La place de la condition `code_matiere = 'ALGO'` change tout :"},{"type":"sql","base":"scolarite","titre":"Condition dans ON : correct","requete":"SELECT e.nom, e.prenom, n.note AS note_algo\nFROM etudiant e\nLEFT JOIN note n ON n.matricule = e.matricule\n               AND n.code_matiere = 'ALGO';","legende":"8 lignes : les 4 étudiants sans note d'ALGO sont gardés avec NULL."},{"type":"sql","base":"scolarite","titre":"Condition dans WHERE : les NULL disparaissent","requete":"SELECT e.nom, e.prenom, n.note AS note_algo\nFROM etudiant e\nLEFT JOIN note n ON n.matricule = e.matricule\nWHERE n.code_matiere = 'ALGO';","legende":"4 lignes seulement : WHERE est appliqué après la jointure, et NULL = 'ALGO' n'est pas vrai. Le LEFT JOIN se comporte alors comme un INNER JOIN."},{"type":"encadre","variante":"retenir","titre":"À retenir","elements":["`INNER JOIN` : seulement les lignes qui ont une correspondance.","`LEFT JOIN` : toutes les lignes de la table de gauche ; NULL quand il n'y a pas de correspondance.","Trouver « les X sans Y » : `X LEFT JOIN Y … WHERE Y.cle IS NULL`.","Une condition sur la table de droite se met dans **ON** si on veut garder les lignes sans correspondance."]},{"type":"quiz","question":"Quelle requête trouve les matières pour lesquelles aucune note n'a été saisie ?","options":["SELECT m.libelle FROM matiere m JOIN note n ON n.code_matiere = m.code_matiere WHERE n.note IS NULL;","SELECT m.libelle FROM matiere m LEFT JOIN note n ON n.code_matiere = m.code_matiere WHERE n.code_matiere IS NULL;","SELECT m.libelle FROM note n LEFT JOIN matiere m ON n.code_matiere = m.code_matiere WHERE m.code_matiere IS NULL;"],"bonneReponse":1,"explication":"On part de la table dont on veut toutes les lignes (matiere), à gauche, puis on garde celles sans correspondance dans note. La 3e requête cherche des notes sans matière, ce qui est impossible grâce à la clé étrangère."},{"type":"titre","contenu":"Exercices d'application"},{"type":"exercice-corrige","niveau":"application","titre":"Application 1 : interne ou externe ?","enonce":"Pour chaque demande, indique s'il faut une jointure interne ou externe, puis écris la requête.","questions":["La liste des étudiants avec le libellé de leur filière.","Toutes les matières, avec le nombre de notes saisies pour chacune (même 0). Écris seulement la jointure, le comptage sera vu dans la leçon suivante.","Les étudiants qui n'ont pas de note d'anglais."],"langage":"sql","solution":"-- 1 : interne (chaque étudiant a une filière)\nSELECT e.nom, e.prenom, f.libelle\nFROM etudiant e\nJOIN filiere f ON e.code_filiere = f.code_filiere;\n\n-- 2 : externe (on veut aussi les matières sans note)\nSELECT m.libelle, n.note\nFROM matiere m\nLEFT JOIN note n ON n.code_matiere = m.code_matiere;\n\n-- 3 : externe + IS NULL\nSELECT e.nom, e.prenom\nFROM etudiant e\nLEFT JOIN note n ON n.matricule = e.matricule AND n.code_matiere = 'ANG'\nWHERE n.matricule IS NULL;","explication":"Question 3 : dans la base d'exemple, tous les étudiants ont une note d'anglais : le résultat est vide, ce qui est une réponse correcte !"},{"type":"titre","contenu":"Sujet type BTS"},{"type":"exercice-corrige","niveau":"bts","titre":"La bibliothèque universitaire","enonce":"La bibliothèque d'une université utilise le schéma suivant :\n\nLIVRE (code_livre, titre, auteur, annee)\nADHERENT (num_adherent, nom, prenom, filiere)\nEMPRUNT (#code_livre, #num_adherent, date_emprunt, date_retour)\n\ndate_retour est NULL tant que le livre n'est pas rendu.","questions":["Affiche le titre des livres et le nom des adhérents pour tous les emprunts en cours (non rendus).","Affiche les livres qui n'ont jamais été empruntés.","Affiche les adhérents qui n'ont jamais emprunté de livre.","Affiche tous les adhérents de la filière IDA, et pour ceux qui ont un emprunt en cours, le titre du livre.","Explique pourquoi une jointure interne ne convient pas pour la question 2."],"langage":"sql","solution":"-- 1\nSELECT l.titre, a.nom, a.prenom\nFROM emprunt em\nJOIN livre l    ON em.code_livre = l.code_livre\nJOIN adherent a ON em.num_adherent = a.num_adherent\nWHERE em.date_retour IS NULL;\n\n-- 2\nSELECT l.code_livre, l.titre\nFROM livre l\nLEFT JOIN emprunt em ON em.code_livre = l.code_livre\nWHERE em.code_livre IS NULL;\n\n-- 3\nSELECT a.num_adherent, a.nom, a.prenom\nFROM adherent a\nLEFT JOIN emprunt em ON em.num_adherent = a.num_adherent\nWHERE em.num_adherent IS NULL;\n\n-- 4 : la condition « en cours » va dans ON pour garder tous les adhérents\nSELECT a.nom, a.prenom, l.titre\nFROM adherent a\nLEFT JOIN emprunt em ON em.num_adherent = a.num_adherent\n                    AND em.date_retour IS NULL\nLEFT JOIN livre l    ON em.code_livre = l.code_livre\nWHERE a.filiere = 'IDA';\n\n-- 5\n-- Une jointure interne ne garde que les livres qui ont au moins une ligne\n-- dans EMPRUNT : les livres jamais empruntés, justement ceux qu'on cherche,\n-- disparaissent du résultat.","explication":"Question 4 : la condition sur la filière concerne la table de gauche (adherent) : elle peut aller dans WHERE. La condition « en cours » concerne la table de droite : elle doit aller dans ON, sinon les adhérents sans emprunt en cours disparaissent."}],"exercice":{"id":"sql-sans-note-bd","titre":"Les étudiants sans note de BD","consigne":"Affiche le matricule, le nom et le prénom des étudiants qui n'ont pas de note en Base de données (code BD).","langage":"sql","base":"scolarite","codeDepart":"-- Étudiants sans note de BD (LEFT JOIN … IS NULL)\n\n","indice":"FROM etudiant e LEFT JOIN note n ON n.matricule = e.matricule AND n.code_matiere = 'BD' WHERE n.matricule IS NULL","solution":"SELECT e.matricule, e.nom, e.prenom\nFROM etudiant e\nLEFT JOIN note n ON n.matricule = e.matricule\n               AND n.code_matiere = 'BD'\nWHERE n.matricule IS NULL;"}},{"slug":"group-by-et-having","titre":"GROUP BY et HAVING : calculer par groupe","duree":"30 min","objectifs":["Regrouper les lignes avec GROUP BY","Respecter la règle des colonnes du SELECT","Filtrer les groupes avec HAVING","Calculer une moyenne pondérée par étudiant"],"resume":{"duree":"1 min 30","scenes":[{"type":"titre","titre":"GROUP BY et HAVING","sousTitre":"Le résumé en 2 minutes","narration":"GROUP BY et HAVING, en deux minutes."},{"type":"code","titre":"Une moyenne par matière","lignes":["SELECT code_matiere, AVG(note)","FROM note","GROUP BY code_matiere;"],"etapes":[{"ligne":1,"variables":{"lignes":"18 notes"}},{"ligne":2,"variables":{"groupes":"ALGO, BD, ANG, COMPTA"},"note":"On forme un paquet par matière"},{"ligne":0,"variables":{"groupes":"ALGO, BD, ANG, COMPTA"},"sortie":"ALGO 13.25 | BD 12 | ANG 11.75 | COMPTA 12","note":"Une ligne par paquet"}],"narration":"GROUP BY range les lignes en paquets, un par matière. Puis la fonction d'agrégation calcule une valeur par paquet : on obtient une moyenne par matière."},{"type":"comparaison","titre":"WHERE ou HAVING ?","colonnes":[{"nom":"WHERE","texte":"Filtre les lignes, avant le regroupement"},{"nom":"HAVING","texte":"Filtre les groupes, après le calcul : HAVING AVG(note) >= 10"}],"narration":"WHERE filtre les lignes avant le regroupement. HAVING filtre les groupes après le calcul : c'est là qu'on met une condition sur une moyenne ou un nombre."},{"type":"points","titre":"La règle d'or","points":["Dans le SELECT : colonnes du GROUP BY","… ou fonctions d'agrégation","Rien d'autre !"],"narration":"La règle d'or : dans le SELECT, on ne met que les colonnes du GROUP BY et des fonctions d'agrégation."},{"type":"exemple","titre":"La moyenne de chaque matière","situation":"Le conseil pédagogique compare les matières pour savoir où renforcer les cours.","langage":"SQL","code":["SELECT code_matiere,","       AVG(note) AS moyenne","FROM note","GROUP BY code_matiere;"],"resultat":["ALGO   | 13.25","ANG    | 11.75","BD     | 12","COMPTA | 12"],"narration":"Exemple concret : GROUP BY forme un groupe par matière, et AVG calcule la moyenne de chaque groupe. L'anglais a la moyenne la plus basse."},{"type":"exemple","titre":"Le tableau d'honneur","situation":"L'école affiche les étudiants dont la moyenne pondérée atteint au moins 13.","langage":"SQL","code":["SELECT e.prenom, ROUND(SUM(n.note *","  m.coefficient) / SUM(m.coefficient), 2)","FROM note n JOIN etudiant e …","            JOIN matiere m …","GROUP BY e.matricule, e.prenom","HAVING SUM(n.note * m.coefficient)","       / SUM(m.coefficient) >= 13;"],"resultat":["Mariam | 16","Yao    | 15.36","Awa    | 13.93","Aya    | 13"],"narration":"Deuxième exemple : on calcule la moyenne pondérée de chaque étudiant, puis HAVING ne garde que les groupes dont la moyenne atteint treize."},{"type":"defi","question":"Pour garder les filières de plus de 3 étudiants : WHERE ou HAVING ?","reponse":"HAVING COUNT(*) > 3","explication":"C'est une condition sur un groupe, calculée après le regroupement. Résultat : IDA (4 étudiants).","narration":"À toi de jouer. Pour garder les filières de plus de trois étudiants, faut-il WHERE ou HAVING ?","narrationReponse":"Réponse : HAVING, car c'est une condition sur le nombre d'étudiants de chaque groupe, calculé après le regroupement. Seule la filière IDA est gardée."}]},"blocs":[{"type":"titre","contenu":"1. Calculer par groupe"},{"type":"texte","contenu":"Au chapitre précédent, `AVG(note)` donnait **une seule** moyenne pour toute la table. Mais le directeur des études veut la moyenne **de chaque matière**. **GROUP BY** range les lignes en **groupes** ayant la même valeur dans une colonne, puis la fonction d'agrégation est calculée **pour chaque groupe**."},{"type":"sql","base":"scolarite","titre":"La moyenne de chaque matière","requete":"SELECT code_matiere, COUNT(*) AS nb_notes, AVG(note) AS moyenne\nFROM note\nGROUP BY code_matiere;","legende":"Une ligne par matière. Vérifie pour ALGO : (15 + 9 + 17 + 12) / 4 = 13,25."},{"type":"sql","base":"scolarite","titre":"Avec une jointure : le libellé et l'effectif de chaque filière","requete":"SELECT f.libelle, COUNT(*) AS effectif\nFROM etudiant e\nJOIN filiere f ON e.code_filiere = f.code_filiere\nGROUP BY f.libelle\nORDER BY effectif DESC;"},{"type":"titre","contenu":"2. La règle d'or du GROUP BY"},{"type":"texte","contenu":"Dans une requête avec GROUP BY, le résultat contient **une ligne par groupe**. Chaque colonne du SELECT doit donc avoir **une seule valeur par groupe**. D'où la règle : dans le SELECT, on ne met que **les colonnes du GROUP BY** et **des fonctions d'agrégation**."},{"type":"tableau","entetes":["Requête","Correcte ?","Pourquoi"],"lignes":[["SELECT code_matiere, AVG(note) FROM note GROUP BY code_matiere","Oui","code_matiere est dans le GROUP BY"],["SELECT matricule, AVG(note) FROM note GROUP BY code_matiere","Non","Plusieurs matricules par matière : lequel afficher ?"],["SELECT e.matricule, e.nom, AVG(n.note) … GROUP BY e.matricule, e.nom","Oui","Les deux colonnes sont dans le GROUP BY"]]},{"type":"encadre","variante":"attention","titre":"SQLite est tolérant, pas l'examinateur","contenu":"Le terminal (SQLite) accepte certaines requêtes qui ne respectent pas la règle et affiche une valeur au hasard. MySQL (en mode strict), SQL Server et Oracle les refusent, et un correcteur les compte fausses. Respecte toujours la règle."},{"type":"titre","contenu":"3. Regrouper par étudiant : la moyenne pondérée"},{"type":"texte","contenu":"Une moyenne de BTS est **pondérée** par les coefficients : on additionne les `note × coefficient`, puis on divise par la somme des coefficients. Il faut donc joindre `note` et `matiere` (pour le coefficient), puis regrouper par étudiant."},{"type":"sql","base":"scolarite","titre":"La moyenne pondérée de chaque étudiant","requete":"SELECT e.matricule, e.nom, e.prenom,\n       ROUND(SUM(n.note * m.coefficient) * 1.0 / SUM(m.coefficient), 2) AS moyenne\nFROM note n\nJOIN etudiant e ON n.matricule = e.matricule\nJOIN matiere m  ON n.code_matiere = m.code_matiere\nGROUP BY e.matricule, e.nom, e.prenom\nORDER BY moyenne DESC;","legende":"Pour Awa Koné : (15×3 + 13,5×3 + 12×1) / (3 + 3 + 1) = 97,5 / 7 ≈ 13,93."},{"type":"titre","contenu":"4. HAVING : filtrer les groupes"},{"type":"texte","contenu":"Pour n'afficher que les étudiants **admis** (moyenne ≥ 10), on ne peut pas écrire `WHERE AVG(note) >= 10` : WHERE est appliqué **avant** le regroupement, quand les moyennes n'existent pas encore. Les conditions sur les **résultats d'agrégation** se mettent dans **HAVING**, placé après GROUP BY."},{"type":"sql","base":"scolarite","titre":"Les matières dont la moyenne est d'au moins 12","requete":"SELECT code_matiere, AVG(note) AS moyenne\nFROM note\nGROUP BY code_matiere\nHAVING AVG(note) >= 12;"},{"type":"sql","base":"scolarite","titre":"WHERE et HAVING dans la même requête","requete":"SELECT matricule, COUNT(*) AS nb_bonnes_notes\nFROM note\nWHERE note >= 12\nGROUP BY matricule\nHAVING COUNT(*) >= 2;","legende":"WHERE garde d'abord les notes ≥ 12 ; GROUP BY les range par étudiant ; HAVING garde les étudiants qui en ont au moins 2."},{"type":"tableau","titre":"L'ordre d'exécution d'une requête","entetes":["Étape","Clause","Rôle"],"lignes":[["1","FROM / JOIN","Prendre et relier les tables"],["2","WHERE","Filtrer les lignes"],["3","GROUP BY","Former les groupes"],["4","HAVING","Filtrer les groupes"],["5","SELECT","Calculer les colonnes affichées"],["6","ORDER BY","Trier le résultat"]],"legende":"C'est pourquoi un alias défini dans SELECT ne peut pas être utilisé dans WHERE (étape 2), mais peut l'être dans ORDER BY (étape 6)."},{"type":"encadre","variante":"retenir","titre":"À retenir","elements":["`GROUP BY col` : une ligne de résultat par valeur de col ; les fonctions d'agrégation sont calculées par groupe.","Dans le SELECT : seulement les colonnes du GROUP BY et des fonctions d'agrégation.","**WHERE** filtre les lignes (avant) ; **HAVING** filtre les groupes (après), avec des conditions sur COUNT, SUM, AVG…","Moyenne pondérée : `SUM(note * coefficient) / SUM(coefficient)`."]},{"type":"quiz","question":"Où placer la condition « filières de plus de 3 étudiants » ?","options":["WHERE COUNT(*) > 3","HAVING COUNT(*) > 3","GROUP BY COUNT(*) > 3"],"bonneReponse":1,"explication":"C'est une condition sur le résultat d'une fonction d'agrégation, calculé par groupe : elle va dans HAVING."},{"type":"quiz","question":"Où placer la condition « seulement les étudiants d'Abidjan » dans une requête qui compte les étudiants par filière ?","options":["WHERE ville = 'Abidjan'","HAVING ville = 'Abidjan'"],"bonneReponse":0,"explication":"C'est une condition sur chaque ligne (chaque étudiant), à appliquer avant le regroupement : WHERE."},{"type":"titre","contenu":"Exercices d'application"},{"type":"exercice-corrige","niveau":"application","titre":"Application 1 : statistiques par groupe","enonce":"Écris les requêtes suivantes sur la base Scolarité.","questions":["Le nombre d'étudiants par ville.","Le nombre d'étudiantes et d'étudiants (par sexe) dans la filière IDA.","La meilleure note de chaque étudiant (matricule, meilleure note).","Le libellé des matières dont la moyenne est inférieure à 12.","Le matricule et la moyenne simple des étudiants qui ont au moins 3 notes."],"langage":"sql","solution":"-- 1\nSELECT ville, COUNT(*) AS nombre\nFROM etudiant\nGROUP BY ville;\n\n-- 2\nSELECT sexe, COUNT(*) AS nombre\nFROM etudiant\nWHERE code_filiere = 'IDA'\nGROUP BY sexe;\n\n-- 3\nSELECT matricule, MAX(note) AS meilleure_note\nFROM note\nGROUP BY matricule;\n\n-- 4\nSELECT m.libelle\nFROM note n\nJOIN matiere m ON n.code_matiere = m.code_matiere\nGROUP BY m.libelle\nHAVING AVG(n.note) < 12;\n\n-- 5\nSELECT matricule, AVG(note) AS moyenne\nFROM note\nGROUP BY matricule\nHAVING COUNT(*) >= 3;","explication":"Question 4 : on peut utiliser AVG dans HAVING sans l'afficher dans le SELECT. Résultat : Anglais (11,75)."},{"type":"titre","contenu":"Sujet type BTS"},{"type":"exercice-corrige","niveau":"bts","titre":"Les statistiques d'une compagnie de transport","enonce":"Une compagnie de cars assure des voyages au départ d'Abidjan. Schéma relationnel :\n\nVILLE (code_ville, nom_ville)\nVOYAGE (num_voyage, date_voyage, #code_ville_arrivee, prix_billet)\nRESERVATION (num_reservation, #num_voyage, nom_passager, nb_places)","questions":["Affiche le nombre de voyages par ville d'arrivée (nom de la ville, nombre de voyages).","Affiche, pour chaque voyage, le numéro et le nombre total de places réservées.","Affiche le numéro et la recette (prix du billet × places réservées) de chaque voyage, du plus rentable au moins rentable.","Affiche le nom des villes ayant reçu plus de 10 voyages en 2025.","Affiche les voyages qui n'ont aucune réservation.","Explique la différence entre WHERE et HAVING en t'appuyant sur la question 4."],"langage":"sql","solution":"-- 1\nSELECT vi.nom_ville, COUNT(*) AS nb_voyages\nFROM voyage vo\nJOIN ville vi ON vo.code_ville_arrivee = vi.code_ville\nGROUP BY vi.nom_ville;\n\n-- 2\nSELECT num_voyage, SUM(nb_places) AS places_reservees\nFROM reservation\nGROUP BY num_voyage;\n\n-- 3\nSELECT vo.num_voyage, SUM(r.nb_places * vo.prix_billet) AS recette\nFROM voyage vo\nJOIN reservation r ON r.num_voyage = vo.num_voyage\nGROUP BY vo.num_voyage\nORDER BY recette DESC;\n\n-- 4\nSELECT vi.nom_ville\nFROM voyage vo\nJOIN ville vi ON vo.code_ville_arrivee = vi.code_ville\nWHERE vo.date_voyage BETWEEN '2025-01-01' AND '2025-12-31'\nGROUP BY vi.nom_ville\nHAVING COUNT(*) > 10;\n\n-- 5\nSELECT vo.num_voyage, vo.date_voyage\nFROM voyage vo\nLEFT JOIN reservation r ON r.num_voyage = vo.num_voyage\nWHERE r.num_reservation IS NULL;\n\n-- 6\n-- WHERE filtre les lignes AVANT le regroupement : ici, il ne garde que\n-- les voyages de 2025 (condition sur chaque voyage).\n-- HAVING filtre les groupes APRÈS le calcul : il ne garde que les villes\n-- dont le nombre de voyages (COUNT, calculé par groupe) dépasse 10.\n-- On ne peut pas écrire WHERE COUNT(*) > 10, car le comptage n'existe\n-- pas encore au moment où WHERE est appliqué.","explication":"Ce sujet balaie tout le chapitre : jointure, GROUP BY, HAVING, LEFT JOIN. Dans la question 3, on pourrait aussi grouper par vo.num_voyage et vo.prix_billet puis écrire SUM(r.nb_places) * vo.prix_billet : les deux réponses sont correctes."}],"exercice":{"id":"sql-effectif-filiere","titre":"L'effectif de chaque filière","consigne":"Affiche le libellé de chaque filière et son nombre d'étudiants, de la filière la plus nombreuse à la moins nombreuse ; à effectif égal, par ordre alphabétique du libellé.","langage":"sql","base":"scolarite","codeDepart":"-- Libellé et effectif de chaque filière\n\n","indice":"JOIN filiere … GROUP BY f.libelle ORDER BY COUNT(*) DESC, f.libelle","solution":"SELECT f.libelle, COUNT(*) AS effectif\nFROM etudiant e\nJOIN filiere f ON e.code_filiere = f.code_filiere\nGROUP BY f.libelle\nORDER BY effectif DESC, f.libelle;"}}]$contenu$::jsonb)
